export const adminCatalogs = Object.freeze(Object.fromEntries(
  ADMIN_LOCALES.map((locale, localeIndex) => [
    locale,
    Object.freeze(Object.fromEntries(
      Object.entries(ADMIN_MESSAGE_ROWS).map(([key, row]) => [key, row[localeIndex]]),
    )),
  ]),
))

export function adminT(locale, key, params = {}) {
  const template = adminCatalogs[locale]?.[key] || adminCatalogs.ru[key] || key
  return template.replace(/\{(\w+)\}/g, (match, name) => (
    Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : match
  ))
}

export function adminTranslator(locale) {
  return (key, params) => adminT(locale, key, params)
}

export function adminLocaleTag(locale) {
  return ({ ru: 'ru-RU', uk: 'uk-UA', pl: 'pl-PL', en: 'en-GB' })[locale] || 'ru-RU'
}
